{"command":"cat > main.c <<'EOF'
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

static const char *usage =
"usage: nnn [OPTIONS] [PATH]\n\n"
"The unorthodox terminal file manager.\n\n"
"positional args:\n"
"  PATH   start dir/file [default: .]\n\n"
"optional args:\n"
" -a      auto NNN_FIFO\n"
" -A      no dir auto-enter during filter\n"
" -b key  open bookmark key (trumps -s/S)\n"
" -B      use bsdtar for archives\n"
" -c      cli-only NNN_OPENER (trumps -e)\n"
" -C      8-color scheme\n"
" -d      detail mode\n"
" -D      dirs in context color\n"
" -e      text in $VISUAL/$EDITOR/vi\n"
" -E      internal edits in EDITOR\n"
" -f      use history file\n"
" -F val  fifo mode [0:preview 1:explore]\n"
" -g      regex filters\n"
" -H      show hidden files\n"
" -i      show current file info\n"
" -J      no auto-advance on selection\n"
" -K      detect key collision and exit\n"
" -l val  set scroll lines\n"
" -n      type-to-nav mode\n"
" -N      use native prompt\n"
" -o      open files only on Enter\n"
" -p file selection file [-:stdout]\n"
" -P key  run plugin key\n"
" -Q      no quit confirmation\n"
" -r      use advcpmv patched cp, mv\n"
" -R      no rollover at edges\n"
" -s name load session by name\n"
" -S      persistent session\n"
" -t secs timeout to lock\n"
" -T key  sort order [a/d/e/r/s/t/v]\n"
" -u      use selection (no prompt)\n"
" -U      show user and group\n"
" -V      show version\n"
" -x      notis, selection sync, xterm title\n"
" -z      in order fuzzy filters\n"
" -0      null separator in picker mode\n"
" -h      show help\n\n"
"v5.2\n"
"BSD 2-Clause\n"
"https://github.com/jarun/nnn\n";

int main(int argc, char **argv) {
    if (argc > 1) {
        for (int i = 1; i < argc; ++i) {
            char *a = argv[i];
            if (a[0] == '-') {
                if (a[1] == '-') {
                    // mimic the original's odd error for double-dash
                    printf("%s: invalid option -- '%c'\n", argv[0], '-');
                    printf("%s", usage);
                    return 0;
                }
                // handle -h
                if (strcmp(a, "-h") == 0) {
                    printf("%s", usage);
                    return 0;
                }
                if (strcmp(a, "-V") == 0) {
                    printf("v5.2\nBSD 2-Clause\nhttps://github.com/jarun/nnn\n");
                    return 0;
                }
                // unknown single-dash option: ignore and continue
            }
        }
    }
    // default behavior: if no args or only path provided, print nothing and exit 0
    // to be safe, mimic typical CLI: do nothing
    return 0;
}
EOF

cat > compile.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
cc -O2 -std=c11 main.c -o executable
# make executable executable
chmod +x executable
EOF

cat > .gitignore <<'EOF'
executable
*.o
*.exe
EOF

chmod +x compile.sh

# build now to verify
./compile.sh

# show help output for verification
./executable --help | sed -n '1,200p'

git init >/dev/null 2>&1 || true
git add . >/dev/null 2>&1
git commit -m "Reimplement nnn CLI help behavior" >/dev/null 2>&1 || true
EOF"}

